import numpy as np

class WavySineValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure input is within bounds
        x = np.clip(x, -5.0, 5.0)
        # Quadratic envelope to create multiple minima
        envelope = 1 + 0.5 * (x**2)
        # Sine wave with varying frequency per dimension
        sine_wave = np.sin(3 * np.pi * x + 0.5 * np.pi * np.arange(self.dim))
        # Combine to create wavy valleys
        return np.sum(envelope * sine_wave**2)

import numpy as np

class WavyValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure x is a numpy array
        x = np.asarray(x)
        # Check dimensionality
        if x.shape[0] != self.dim:
            raise ValueError(f"Expected input of dimension {self.dim}, got {x.shape[0]}")

        # Separable, multimodal component per dimension
        # Combines a quadratic term with a periodic sinusoidal term
        term = x**2 + 0.5 * np.sin(3 * np.pi * x)
        return np.sum(term)

