import numpy as np

class FractionalPowerValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure input is within bounds
        x = np.clip(x, -5.0, 5.0)
        # Fractional power term to create multiple minima
        fractional_power = np.abs(x)**1.5
        # Sinusoidal perturbation with varying frequency per dimension
        sine_perturbation = np.sin(2 * np.pi * x + 0.5 * np.pi * np.arange(self.dim))
        # Combine to create fractional power valleys
        return np.sum(fractional_power + 0.5 * sine_perturbation**2)
